# Run ON an instance. Every check here corresponds to a failure
# that has actually cost work before.
set -uo pipefail
source /root/.dreamer_vast_env
fail=0
ok () { printf "  PASS %s\n" "$1"; }
bad () { printf "  FAIL %s\n" "$1"; fail=1; }

echo "== fork present (an empty $REPO fails as scattered ENOENT, never one message) =="
for f in scripts/env.sh scripts/ops/instance_helpers.sh probing/__init__.py; do
  [ -e "$REPO/$f" ] && ok "$f" || bad "MISSING $REPO/$f -- run push-repo"
done

echo "== interpreter =="
"${CONDA_ENV:-/venv/main}/bin/python" -c "import sys" 2>/dev/null \
  && ok "python in $CONDA_ENV" || bad "python broken in ${CONDA_ENV:-/venv/main}"

echo "== transfer tooling =="
for b in rsync tar; do
  p="$(command -v "$b" 2>/dev/null)"
  if [ -z "$p" ]; then bad "MISSING $b"
  elif [ ! -x "$p" ]; then bad "$b not executable ($p)"
  elif [ ! -s "$p" ]; then bad "$b is a 0-byte stub ($p) -- reinstall it"
  else ok "$b $(du -h "$p" | cut -f1)"; fi
done

echo "== disk =="
pct="$(df -P "$RUNROOT" | awk 'NR==2{gsub(/%/,"",$5); print $5}')"
[ "${pct:-100}" -lt 90 ] && ok "disk ${pct}% used" || bad "disk ${pct}% used"

echo "== producer reads every variable the wave sets =="
if [ ! -e "$REPO/scripts/uncfield_se.sbatch" ]; then bad "MISSING producer scripts/uncfield_se.sbatch"; else
  grep -qE '[$]\{?DISTRACTOR_MOD_HI\b' "$REPO/scripts/uncfield_se.sbatch" && ok "scripts/uncfield_se.sbatch reads \$DISTRACTOR_MOD_HI" || bad "STALE PRODUCER: scripts/uncfield_se.sbatch never reads \$DISTRACTOR_MOD_HI -- the wave sets it and it would bind NOTHING (run push-repo)"
