  grep -qE '[$]\{?DISTRACTOR_SCALE\b' "$REPO/scripts/uncfield_se.sbatch" && ok "scripts/uncfield_se.sbatch reads \$DISTRACTOR_SCALE" || bad "STALE PRODUCER: scripts/uncfield_se.sbatch never reads \$DISTRACTOR_SCALE -- the wave sets it and it would bind NOTHING (run push-repo)"
  grep -qE '[$]\{?PENALTY_GATE_INDEX\b' "$REPO/scripts/uncfield_se.sbatch" && ok "scripts/uncfield_se.sbatch reads \$PENALTY_GATE_INDEX" || bad "STALE PRODUCER: scripts/uncfield_se.sbatch never reads \$PENALTY_GATE_INDEX -- the wave sets it and it would bind NOTHING (run push-repo)"
  grep -qE '[$]\{?PENALTY_GATE_KEY\b' "$REPO/scripts/uncfield_se.sbatch" && ok "scripts/uncfield_se.sbatch reads \$PENALTY_GATE_KEY" || bad "STALE PRODUCER: scripts/uncfield_se.sbatch never reads \$PENALTY_GATE_KEY -- the wave sets it and it would bind NOTHING (run push-repo)"
  grep -qE '[$]\{?PENALTY_GATE_THRESHOLD\b' "$REPO/scripts/uncfield_se.sbatch" && ok "scripts/uncfield_se.sbatch reads \$PENALTY_GATE_THRESHOLD" || bad "STALE PRODUCER: scripts/uncfield_se.sbatch never reads \$PENALTY_GATE_THRESHOLD -- the wave sets it and it would bind NOTHING (run push-repo)"
