  grep -qE '[$]\{?PENALTY_SCALE\b' "$REPO/scripts/uncfield_se.sbatch" && ok "scripts/uncfield_se.sbatch reads \$PENALTY_SCALE" || bad "STALE PRODUCER: scripts/uncfield_se.sbatch never reads \$PENALTY_SCALE -- the wave sets it and it would bind NOTHING (run push-repo)"
  grep -qE '[$]\{?RUN_ID\b' "$REPO/scripts/uncfield_se.sbatch" && ok "scripts/uncfield_se.sbatch reads \$RUN_ID" || bad "STALE PRODUCER: scripts/uncfield_se.sbatch never reads \$RUN_ID -- the wave sets it and it would bind NOTHING (run push-repo)"
